function setPartnerLoginRole(role) {
  partnerLoginRole = role === "master" ? "master" : "supplier";
  const isSupplier = partnerLoginRole === "supplier";
  /* 로그인 화면부터 역할 색을 나눈다: 위탁셀러 파랑 · 공급사 검정 · 마스터 보라 */
  document.body.dataset.role = partnerLoginRole;
  document.getElementById("partnerLoginView").classList.toggle("is-master", !isSupplier);
  document.getElementById("partnerBadge").textContent = isSupplier ? "두고 파트너센터" : "두고 마스터센터";
  document.getElementById("partnerMessageKicker").textContent = isSupplier ? "SUPPLIER CENTER" : "MASTER CENTER";
  document.getElementById("partnerFeatureList").innerHTML = (isSupplier
    ? ["상품·재고·공급가 실시간 관리", "배송준비중 주문 송장 자동 발급", "월별 정산 리포트와 수수료 내역 확인"]
    : ["매출·수수료 7%·구독 순이익을 한눈에", "두고톡 상담·환불·정산을 한곳에서", "공급사·위탁셀러 관리와 이용 정지"]).map(text => `<li><i>✓</i>${text}</li>`).join("");
  document.getElementById("partnerLoginKicker").textContent = isSupplier ? "PARTNER CENTER" : "MASTER CENTER";
  document.getElementById("partnerTypingText")?.startTypingRefresh?.();
  document.getElementById("partnerLoginTitle").textContent = isSupplier ? "공급사 로그인" : "관리자 로그인";
  document.getElementById("partnerLoginDescription").textContent = isSupplier ? "상품·재고·주문·송장을 관리합니다." : "전체 회원·상품·주문·이력을 관리합니다.";
  document.getElementById("supplierSignupPrompt").hidden = !isSupplier;
  const roleSwitch = document.getElementById("partnerRoleSwitch");
  roleSwitch.dataset.partnerRole = isSupplier ? "master" : "supplier";
  roleSwitch.textContent = isSupplier ? "관리자 로그인" : "공급사 로그인";
  document.getElementById("partnerDemoAccounts").innerHTML = `<div><button type="button" data-partner-demo="${partnerLoginRole}">데모 계정으로 체험하기 <b>${isSupplier ? "공급사" : "마스터"}</b></button></div>`;
  document.getElementById("partnerLoginId").value = "";
  document.getElementById("partnerLoginPassword").value = "";
  document.getElementById("partnerLoginError").textContent = "";
}

function showApp(accountId, staff = null) {
  const account = getAccount(accountId);
  if (!account || account.status !== "approved") return showLogin();
  currentAccount = { roles: [account.role], ...account, id: account.loginId || accountId };
  if (staff) currentAccount.staff = { id: staff.id, name: staff.name, email: staff.email, title: staff.title, permissions: { ...staff.permissions } };
  activeRole = currentAccount.role;
  activeMenuIndex = 0;
  sellerCategory = "전체보기";
  sellerCategoryGroup = "전체";
  sellerCategorySub = "전체보기";
  sellerCategoryDetail = "전체보기";
  sellerShippingFilter = "all";
  sellerCountry = "전체 국가";
  sellerBrand = "전체 브랜드";
  sellerProductSearch = "";
  sellerOrderSearch = "";
  sellerOrderStage = "all";
  activeChatConnectionId = "";
  chatRoomFilter = "all";
  chatRoomSearch = "";
  editMode = false;
  refundMonth = "all";
  refundSearch = "";
  refundTypeFilter = "all";
  refundOpenOnly = false;
  supplierLowStockOnly = false;
  sessionStorage.setItem(AUTH_KEY, staff ? `staff:${staff.email}` : (currentAccount.loginId || accountId));
  document.getElementById("loginView").hidden = true;
  document.getElementById("partnerLoginView").hidden = true;
  document.getElementById("signupView").hidden = true;
  document.getElementById("appView").hidden = false;
  closeMobileSidebar();
  render();
  updateAccountUI();
  window.scrollTo({ top: 0 });
  clearTimeout(showApp.collectTimer);
  if (activeRole === "seller") showApp.collectTimer = setTimeout(maybeAutoCollectOrders, 1500);
  if (activeRole === "master") setTimeout(maybeAutoDailyReport, 2500);
}
setInterval(() => { if (!document.hidden) { maybeAutoCollectOrders(); maybeAutoDailyReport(); } }, 60 * 1000);

function initAuth() {
  const rememberedId = localStorage.getItem(REMEMBER_KEY) || "";
  document.getElementById("loginId").value = rememberedId;
  document.getElementById("rememberId").checked = Boolean(rememberedId);
  const sessionId = (sessionStorage.getItem(AUTH_KEY) || "").toLowerCase();
  const sessionStaff = sessionId.startsWith("staff:") ? staffByEmail(sessionId.slice(6)) : null;
  if (sessionStaff?.status === "active" && getAccount(sessionStaff.ownerLoginId)?.status === "approved") showApp(sessionStaff.ownerLoginId, sessionStaff);
  else if (getAccount(sessionId)?.status === "approved") showApp(sessionId);
  else showLogin();
}

function showSignup(role = "seller", returnTarget = "seller") {
  const normalizedRole = role === "supplier" ? "supplier" : "seller";
  signupReturnTarget = returnTarget;
  document.getElementById("loginView").hidden = true;
  document.getElementById("partnerLoginView").hidden = true;
  document.getElementById("appView").hidden = true;
  document.getElementById("signupView").hidden = false;
  document.getElementById("signupFormWrap").hidden = false;
  document.getElementById("signupComplete").hidden = true;
  const signupFormEl = document.getElementById("signupForm");
  signupFormEl.reset();
  signupFormEl.classList.remove("docs-later");
  signupFormEl.querySelectorAll("[data-file-label]").forEach(label => { label.textContent = "📄 사진 찍기 또는 파일 선택"; label.closest(".signup-file").classList.remove("has-file"); });
  signupFormEl.querySelector("[data-business-result]").hidden = true;
  signupFormEl.querySelector("[data-phone-code-row]").hidden = true;
  signupPhoneCode = "";
  fillBankSelect(signupFormEl);
  document.getElementById("signupRole").value = normalizedRole;
  setPhoneStatus(false);
  document.getElementById("signupTitle").textContent = normalizedRole === "supplier" ? "두고 공급사 가입" : "두고 가입하기";
  document.getElementById("signupTypeLabel").textContent = normalizedRole === "supplier" ? "SUPPLIER REGISTRATION" : "SELLER REGISTRATION";
  document.getElementById("signupDescription").textContent = normalizedRole === "supplier" ? "4단계로 입점을 신청해요. 사업자 서류는 나중에 올려도 돼요." : "사업자라면 4단계로 가입해요. 서류는 나중에 올려도 돼요.";
  document.getElementById("signupVisualEyebrow").textContent = normalizedRole === "supplier" ? "DOOGO SUPPLIER" : "DOOGO SELLER";
  document.getElementById("signupVisualTitle").innerHTML = normalizedRole === "supplier" ? "좋은 상품을 공급하고,<br>새로운 판매처를 만나세요." : "좋은 공급상품을 골라,<br>바로 판매를 시작하세요.";
  document.getElementById("signupVisualDescription").innerHTML = normalizedRole === "supplier" ? "상품 등록부터 주문·송장·정산까지<br>두고가 공급사의 운영을 하나로 연결합니다." : "상품 소싱부터 주문·송장·가격 변경까지<br>두고가 공급과 판매를 하나의 흐름으로 연결합니다.";
  setSignupStep(restoreSignupDraft(normalizedRole));
  window.scrollTo({ top: 0 });
}

function setSignupStep(step) {
  signupStep = Math.max(1, Math.min(4, Number(step) || 1));
  document.querySelectorAll("[data-signup-step]").forEach(panel => {
    const active = Number(panel.dataset.signupStep) === signupStep;
    panel.hidden = !active;
    panel.classList.toggle("active", active);
  });
  document.querySelectorAll("[data-signup-step-nav]").forEach(button => {
    const value = Number(button.dataset.signupStepNav);
    button.classList.toggle("active", value === signupStep);
    button.classList.toggle("complete", value < signupStep);
    const badge = button.querySelector("b");
    if (badge) badge.textContent = value < signupStep ? "✓" : String(value);
  });
  document.querySelectorAll("[data-signup-error]").forEach(element => element.textContent = "");
  document.querySelector(`[data-signup-step="${signupStep}"] input:not([type="hidden"])`)?.focus();
}

function validateSignupStep(step) {
  const form = document.getElementById("signupForm");
  const panel = form.querySelector(`[data-signup-step="${step}"]`);
  const error = panel?.querySelector("[data-signup-error]");
  const fail = (message, name) => { if (error) error.textContent = message; const field = name && form.elements[name]; if (field?.focus) field.focus(); return false; };
  if (step === 1) {
    const email = String(form.elements.email.value || "").trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return fail("이메일 주소를 확인해 주세요.", "email");
    if (getAccount(email)) return fail("이미 가입된 이메일이에요. 로그인하거나 비밀번호 찾기를 이용해 주세요.", "email");
    const password = form.elements.password.value;
    if (password.length < 8 || !/[A-Za-z]/.test(password) || !/\d/.test(password)) return fail("비밀번호는 영문과 숫자를 섞어 8자 이상으로 만들어 주세요.", "password");
    if (password !== form.elements.passwordConfirm.value) return fail("비밀번호가 서로 달라요.", "passwordConfirm");
    if (!form.elements.phoneVerified.value) return fail("휴대폰 인증을 해 주세요. ‘인증번호 받기’를 누르면 돼요.", "contact");
  }
  if (step === 2) {
    if (!isValidBusinessNo(form.elements.businessNo.value)) return fail("사업자등록번호 10자리를 확인해 주세요.", "businessNo");
    if (!form.elements.businessVerified.value) return fail("‘사업자 진위 확인하기’를 눌러 사업자 확인을 해 주세요.");
    if (!form.elements.company.value.trim()) return fail("상호명을 넣어 주세요.", "company");
  }
  if (step === 3 && !form.elements.docsLater.checked) {
    if (!signupFileName(form.elements.businessFile)) return fail("사업자등록증을 올려 주세요. 지금 없으면 아래 ‘나중에 올리기’를 체크해요.");
    if (!form.elements.bankName.value) return fail("정산·환불 받을 은행을 골라 주세요.", "bankName");
    if (!form.elements.bankAccountHolder.value.trim()) return fail("예금주를 넣어 주세요.", "bankAccountHolder");
    if (form.elements.bankAccountNumber.value.replace(/\D/g, "").length < 8) return fail("계좌번호를 확인해 주세요.", "bankAccountNumber");
    if (!signupFileName(form.elements.bankbookFile)) return fail("통장 사본을 올려 주세요.");
  }
  if (step === 4) {
    if (!String(form.elements.referralCode.value || "").trim()) return fail("추천인 코드는 필수예요.", "referralCode");
    if (!form.elements.terms.checked || !form.elements.privacy.checked) return fail("필수 약관 2개에 동의해 주세요.");
  }
  if (error) error.textContent = "";
  return true;
}

function returnToLogin() {
  document.getElementById("signupView").hidden = true;
  if (signupReturnTarget === "partner") showPartnerLogin("supplier");
  else showLogin();
}

function nextMemberId() {
  const largest = Math.max(...state.members.map(member => Number(member.id.replace(/\D/g, "")) || 1000));
  return `MB-${largest + 1}`;
}

function sectionHero(title, description, action = "") {
  return `<div class="hero-row section-hero"><div class="hero-copy"><h2>${title}</h2><p>${description}</p></div>${action}</div>`;
}

function catalogBaseProducts() {
  const connectedSuppliers = new Set(currentSellerConnections().map(connection => connection.supplierLoginId));
  const query = sellerProductSearch.trim().toLowerCase();
  return state.products.filter(product => {
    if (supplierBlocked(product.supplierLoginId)) return false;
    const matchesText = !query || [product.id, product.name, product.supplier, productBrand(product), product.origin, product.originCountry, ...productCategoryPath(product), ...productOptions(product).map(option => option.name)].some(value => String(value || "").toLowerCase().includes(query));
    const matchesShipping = sellerShippingFilter === "all" || (sellerShippingFilter === "overseas" ? product.shippingType === "overseas" : product.shippingType !== "overseas");
    const matchesCountry = sellerCountry === "전체 국가" || (product.originCountry || "대한민국") === sellerCountry;
    return isCatalogVisible(product) && connectedSuppliers.has(product.supplierLoginId) && productVisibleToSeller(product, currentAccount?.loginId) && matchesText && matchesShipping && matchesCountry;
  });
}
function isCatalogVisible(product) { return product.status === "판매중" && product.soldOut !== "품절" && product.exposure !== "미노출" && product.visibility !== "비노출"; }
function productMatchesCategory(product, path) {
  const [group, mid, sub, detail] = path;
  return (!group || group === "전체" || (product.categoryGroup || "식품") === group)
    && (!mid || mid === "전체보기" || product.category === mid)
    && (!sub || sub === "전체보기" || product.categorySub === sub)
    && (!detail || detail === "전체보기" || product.categoryDetail === detail);
}
function sellerCatalogProducts() {
  const path = [sellerCategoryGroup, sellerCategory, sellerCategorySub, sellerCategoryDetail];
  const list = catalogBaseProducts().filter(product => productMatchesCategory(product, path));
  if (sellerCatalogSort === "margin") return [...list].sort((a, b) => margin(b.supply, b.recommended) - margin(a.supply, a.recommended));
  if (sellerCatalogSort === "supply") return [...list].sort((a, b) => Number(a.supply) - Number(b.supply));
  return list;
}

/* 두고 기본 상품 이미지 (assets/product-00 ~ 34.jpg). 공급사가 사진을 올리지 않으면 이 중 하나를 대표 이미지로 쓴다. */
const PRODUCT_IMAGE_COUNT = 35;
function productAssetSrc(index) { const n = ((Math.round(Number(index) || 0) % PRODUCT_IMAGE_COUNT) + PRODUCT_IMAGE_COUNT) % PRODUCT_IMAGE_COUNT; return `assets/product-${String(n).padStart(2, "0")}.jpg`; }
/* 공급사가 직접 올린 사진(product.photos, 첫 장이 대표)이 있으면 그 사진, 없으면 두고 기본 이미지 */
const PRODUCT_PHOTO_MAX = 10;
function productOwnPhotos(product) { return (product?.photos || []).map(imgSrc).filter(Boolean); }
/* 휴대폰 사진첩에 따라 파일 종류(type)가 비어서 오는 경우가 있어 확장자로도 사진인지 확인한다 */
function isImageFile(file) { return Boolean(file) && (/^image\//.test(file.type || "") || (!file.type && /\.(jpe?g|png|gif|webp|heic|heif|bmp|avif)$/i.test(file.name || ""))); }
function productMainSrc(product) { return productOwnPhotos(product)[0] || productAssetSrc(product?.imageIndex); }
function productPhoto(product, className = "") {
  /* 두고 기본 이미지(세로형·위쪽이 비어 있음)는 상품이 있는 아래쪽을 기준으로 잘라 여백 없이 보이게 한다 */
  const stock = !productOwnPhotos(product).length;
  return `<img class="product-photo ${className}${stock ? " is-stock" : ""}" src="${escapeHtml(productMainSrc(product))}" alt="${escapeHtml(product?.name || "상품 이미지")}">`;
}
/* 상품 노출 범위: '선택 셀러만'이면 공급사가 체크한 셀러에게만 상품 소싱·브랜드관에 보인다 */
function productVisibleToSeller(product, sellerLoginId) {
  if (product?.visibility === "비노출") return false;
  if (product?.visibility === "선택 셀러") return (product.visibleSellers || []).includes(sellerLoginId);
  return true;
}
function productSupplierConnections(product) {
  const supplierLoginId = product?.supplierLoginId || currentAccount?.loginId;
  return state.connections.filter(connection => connection.supplierLoginId === supplierLoginId && connection.status === "connected");
}

/* 네이버쇼핑 대분류 아이콘 (쇼핑 앱의 카테고리 메뉴처럼 한눈에 고를 수 있게) */
const NAVER_CATEGORY_ICONS = { "패션의류": "👗", "패션잡화": "👜", "화장품/미용": "💄", "디지털/가전": "💻", "가구/인테리어": "🛋️", "출산/육아": "🍼", "식품": "🍎", "스포츠/레저": "⚽", "생활/건강": "🧴", "여가/생활편의": "🎟️", "면세점": "✈️" };
function selectedMarketCategoryPath() {
  return [sellerCategoryGroup === "전체" ? "" : sellerCategoryGroup, sellerCategory === "전체보기" ? "" : sellerCategory, sellerCategorySub === "전체보기" ? "" : sellerCategorySub, sellerCategoryDetail === "전체보기" ? "" : sellerCategoryDetail];
}
function marketCategoryNavigator() {
  const base = catalogBaseProducts();
  const selected = selectedMarketCategoryPath();
  const depth = selected.filter(Boolean).length;
  const topCount = name => base.filter(product => productMatchesCategory(product, [name])).length;
  const rail = `<div class="cat-rail ${depth ? "collapsed" : ""}" aria-label="네이버쇼핑 대분류">
    <button type="button" class="cat-rail-item ${depth === 0 ? "active" : ""}" data-action="category-crumb" data-level="0"><span class="cat-rail-icon" aria-hidden="true">🛍️</span><b>전체</b><em>${base.length}</em></button>${Object.keys(naverCategoryTree).map(name => { const count = topCount(name); return `<button type="button" class="cat-rail-item ${selected[0] === name ? "active" : ""} ${count ? "" : "empty"}" data-action="category-chip" data-level="1" data-value="${escapeHtml(name)}"><span class="cat-rail-icon" aria-hidden="true">${NAVER_CATEGORY_ICONS[name] || "•"}</span><b>${escapeHtml(name)}</b><em>${count}</em></button>`; }).join("")}</div>`;
  let sub = "";
  if (depth >= 1) {
    const chipLevel = Math.min(depth + 1, 4);
    const chipPath = depth === 4 ? selected.slice(0, 3) : selected.slice(0, depth);
    const options = categoryLevelOptions(chipLevel, chipPath);
    const countFor = option => { const path = [...chipPath]; path[chipLevel - 1] = option; return base.filter(product => productMatchesCategory(product, path)).length; };
    const crumbs = selected.filter(Boolean).map((name, index) => `${index ? `<i aria-hidden="true">›</i>` : ""}<button type="button" class="${index === depth - 1 ? "current" : ""}" data-action="category-crumb" data-level="${index + 1}">${escapeHtml(name)}</button>`).join("");
    const levelName = ["대분류", "중분류", "소분류", "세분류"][chipLevel - 1];
    const chips = options.map(option => { const count = countFor(option); const active = selected[chipLevel - 1] === option; return `<button type="button" class="category-chip ${active ? "active" : ""} ${count ? "" : "empty"}" data-action="category-chip" data-level="${chipLevel}" data-value="${escapeHtml(option)}"><b>${escapeHtml(option)}</b><em>${count}</em></button>`; }).join("");
    sub = `<div class="cat-sub"><div class="cat-sub-head"><nav class="category-crumbs" aria-label="카테고리 경로">${crumbs}</nav><button type="button" class="cat-clear" data-action="clear-market-filter" data-filter="category" aria-label="카테고리 선택 해제"><i aria-hidden="true">×</i> <span class="cat-clear-word">카테고리 </span>해제</button></div><div class="category-chip-row" aria-label="${levelName}">${chips || `<span class="category-chip-empty">가장 아래 단계예요.</span>`}</div></div>`;
  }
  return `<div class="category-nav">
    <div class="category-nav-head"><span class="category-nav-label">카테고리 <small>네이버쇼핑 기준</small></span><div class="category-search-box"><input type="text" class="category-search-input" data-category-search placeholder="카테고리 검색 (예: 꿀, 김치)" autocomplete="off"><div class="category-search-results" data-category-search-results hidden></div></div></div>
    ${rail}${sub}
  </div>`;
}
/* 지금 걸려 있는 조건을 칩으로 보여주고, × 로 하나씩 풀 수 있게 한다. */
function marketActiveFilters() {
  const chips = [];
  const path = selectedMarketCategoryPath().filter(Boolean);
  if (path.length) chips.push(["category", `카테고리 · ${path.join(" › ")}`]);
  if (sellerShippingFilter !== "all") chips.push(["shipping", sellerShippingFilter === "overseas" ? "해외소싱" : "국내배송"]);
  if (sellerCountry !== "전체 국가") chips.push(["country", `나라 · ${sellerCountry}`]);
  if (sellerProductSearch.trim()) chips.push(["search", `검색어 · ${sellerProductSearch.trim()}`]);
  if (!chips.length) return "";
  return `<div class="market-active-filters"><span class="market-active-label">선택한 조건</span>${chips.map(([key, label]) => `<button type="button" class="filter-chip" data-action="clear-market-filter" data-filter="${key}" aria-label="${escapeHtml(label)} 조건 해제"><b>${escapeHtml(label)}</b><i aria-hidden="true">×</i></button>`).join("")}${chips.length > 1 ? `<button type="button" class="filter-chip-reset" data-action="reset-market-filter">전체 해제</button>` : ""}</div>`;
}
function marketViewToggle() {
  return `<div class="market-view-toggle" role="group" aria-label="상품 보기 방식"><button type="button" class="${marketViewMode === "grid" ? "active" : ""}" data-action="set-market-view" data-view="grid" aria-label="바둑판 보기"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="8" height="8" rx="1.5"/><rect x="13" y="3" width="8" height="8" rx="1.5"/><rect x="3" y="13" width="8" height="8" rx="1.5"/><rect x="13" y="13" width="8" height="8" rx="1.5"/></svg></button><button type="button" class="${marketViewMode === "list" ? "active" : ""}" data-action="set-market-view" data-view="list" aria-label="목록 보기"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="4" rx="1"/><rect x="3" y="10" width="18" height="4" rx="1"/><rect x="3" y="16" width="18" height="4" rx="1"/></svg></button></div>`;
}
function marketProductListing(products, empty) {
  return marketViewMode === "list"
    ? `<div class="market-product-list">${products.length ? products.map(productRowSellerList).join("") : empty}</div>`
    : `<div class="product-card-grid shop-grid">${products.length ? products.map(productRowSeller).join("") : empty}</div>`;
}
function marketToolbar() {
  const countries = ["전체 국가", ...new Set(state.products.map(product => product.originCountry || "대한민국"))];
  return `<div class="market-toolbar market-toolbar-shop">
    <label class="catalog-search"><span aria-hidden="true">⌕</span><input id="sellerCatalogSearch" value="${escapeHtml(sellerProductSearch)}" placeholder="상품명·원산지·카테고리 검색" autocomplete="off" enterkeyhint="search">${sellerProductSearch ? `<button type="button" class="search-clear" data-action="clear-market-filter" data-filter="search" aria-label="검색어 지우기">×</button>` : ""}</label>
    ${marketCategoryNavigator()}
    <div class="market-filter-row">
      <div class="shipping-tabs" role="group" aria-label="배송 구분"><button type="button" class="${sellerShippingFilter === "all" ? "active" : ""}" data-action="filter-shipping" data-filter="all">전체</button><button type="button" class="${sellerShippingFilter === "domestic" ? "active" : ""}" data-action="filter-shipping" data-filter="domestic">국내배송</button><button type="button" class="${sellerShippingFilter === "overseas" ? "active" : ""}" data-action="filter-shipping" data-filter="overseas">해외소싱</button></div>
      <label class="market-select"><span>나라</span><select id="marketCountrySelect">${countries.map(country => `<option ${sellerCountry === country ? "selected" : ""}>${escapeHtml(country)}</option>`).join("")}</select></label>
      <label class="market-select"><span>정렬</span><select id="marketSortSelect"><option value="recommend" ${sellerCatalogSort === "recommend" ? "selected" : ""}>추천순</option><option value="margin" ${sellerCatalogSort === "margin" ? "selected" : ""}>마진 높은순</option><option value="supply" ${sellerCatalogSort === "supply" ? "selected" : ""}>공급가 낮은순</option></select></label>
    </div>
    ${marketActiveFilters()}
    <div class="market-result-row"><span>검색 결과 <b>${sellerCatalogProducts().length}</b>개</span>${marketViewToggle()}</div>
  </div>`;
}

const BRAND_TAGLINES = { "청송골 과수원": "해발 500m 청송 산지에서 키운 아삭한 사과", "키위네이처": "뉴질랜드 정식 수입 마누카꿀 전문", "숲내음 버섯농장": "참나무 원목에서 키운 무농약 버섯", "제주 한결농원": "제주 서귀포 하우스 감귤 산지직송", "서해바다상회": "서해 당일 조업 꽃게·수산물", "제주 은빛수산": "제주 은갈치 손질·급랭 전문", "어머니손맛 김치": "국산 재료로 담근 3도씨 숙성 김치", "오지그린팜": "호주 청정지역 과일 수입", "운남 산채방": "중국 운남성 산지 건조 버섯" };
function brandProfiles() {
  const connected = new Set(currentSellerConnections().map(connection => connection.supplierLoginId));
  const map = new Map();
  state.products.filter(product => product.status === "판매중" && productVisibleToSeller(product, currentAccount?.loginId) && connected.has(product.supplierLoginId) && !supplierBlocked(product.supplierLoginId)).forEach(product => {
    const name = productBrand(product);
    if (!map.has(name)) map.set(name, { name, supplier: product.supplier, supplierLoginId: product.supplierLoginId, products: [], categories: new Set(), countries: new Set() });
    const brand = map.get(name);
    brand.products.push(product); brand.categories.add(product.category); brand.countries.add(product.originCountry || "대한민국");
  });
  return [...map.values()].map(brand => ({ ...brand, cover: brand.products[0], tagline: BRAND_TAGLINES[brand.name] || `${brand.supplier} 공급 브랜드`, categories: [...brand.categories], countries: [...brand.countries], overseas: brand.products.some(product => product.shippingType === "overseas") }));
}
function brandLogo(name) { return `<span class="brand-logo" aria-hidden="true">${escapeHtml(String(name).replace(/^(제주|서해)\s*/, "").slice(0, 1))}</span>`; }
function brandBannerCard(brand) {
  return `<button type="button" class="brand-banner-card" data-action="select-brand" data-brand="${escapeHtml(brand.name)}" data-brand-search="${escapeHtml(`${brand.name} ${brand.supplier} ${brand.categories.join(" ")} ${brand.products.map(product => product.name).join(" ")}`.toLowerCase())}" data-brand-category="${escapeHtml(brand.categories.join("|"))}">
    <span class="brand-banner-image">${productPhoto(brand.cover, "brand-banner-photo")}<em>${brand.overseas ? `해외 · ${escapeHtml(brand.countries.join("·"))}` : "국내 브랜드"}</em></span>
    <span class="brand-banner-body">${brandLogo(brand.name)}<span><b>${escapeHtml(brand.name)}</b><small>${escapeHtml(brand.tagline)}</small><i>${escapeHtml(brand.categories.join(" · "))} · 상품 ${brand.products.length}개</i></span><strong>브랜드 상품 보기 →</strong></span>
  </button>`;
}
function filterBrandBanners() {
  const panel = document.querySelector(".brand-directory-panel");
  if (!panel) return;
  const query = (panel.querySelector("[data-brand-search-input]")?.value || "").trim().toLowerCase();
  const tab = panel.querySelector("[data-brand-tab].active")?.dataset.brandTab || "";
  let visible = 0;
  panel.querySelectorAll(".brand-banner-card").forEach(card => { const show = (!query || card.dataset.brandSearch.includes(query)) && (!tab || card.dataset.brandCategory.split("|").includes(tab)); card.hidden = !show; if (show) visible += 1; });
  const empty = panel.querySelector(".brand-empty"); if (empty) empty.hidden = visible > 0;
}
function brandDirectoryTemplate() {
  const brands = brandProfiles();
  const categories = [...new Set(brands.flatMap(brand => brand.categories))];
  return `<div class="market-intro brand-intro"><div><b>브랜드로 상품 찾기</b><span>브랜드 배너를 누르면 그 브랜드 상품만 모아서 보여 드려요.</span></div><button type="button" class="secondary-button" data-action="close-brand-directory">카테고리로 찾기 →</button></div>
    <section class="panel brand-directory-panel">
      <div class="brand-directory-tools"><label class="brand-search"><span aria-hidden="true">⌕</span><input type="text" data-brand-search-input placeholder="브랜드명·상품명으로 찾기 (예: 사과, 마누카)" autocomplete="off"></label>
      <div class="brand-category-tabs" role="tablist"><button type="button" class="active" data-brand-tab="">전체 ${brands.length}</button>${categories.map(category => `<button type="button" data-brand-tab="${escapeHtml(category)}">${escapeHtml(category)} ${brands.filter(brand => brand.categories.includes(category)).length}</button>`).join("")}</div></div>
      <div class="brand-banner-grid">${brands.length ? brands.map(brandBannerCard).join("") : ""}</div>
      <div class="empty brand-empty" ${brands.length ? "hidden" : ""}><b>찾는 브랜드가 없어요.</b><span>다른 이름으로 검색해 보세요.</span></div>
    </section>`;
}
function selectedBrandHero(brand) {
  return `<section class="brand-hero">${productPhoto(brand.cover, "brand-hero-photo")}<div class="brand-hero-body">${brandLogo(brand.name)}<div><span>BRAND</span><h2>${escapeHtml(brand.name)}</h2><p>${escapeHtml(brand.tagline)}</p><small>공급사 ${escapeHtml(brand.supplier)} · ${escapeHtml(brand.categories.join(" · "))} · 상품 ${brand.products.length}개</small></div></div><div class="brand-hero-actions"><button type="button" class="white-button" data-action="select-brand" data-brand="전체 브랜드">← 브랜드 목록</button><button type="button" class="brand-hero-clear" data-action="select-brand" data-brand="전체 브랜드" aria-label="브랜드 선택 해제">× 브랜드 해제</button></div></section>`;
}
function sellerBrandSourcingTemplate() {
  const brand = sellerBrand === "전체 브랜드" ? null : brandProfiles().find(item => item.name === sellerBrand);
  if (!brand) { sellerBrand = "전체 브랜드"; return brandDirectoryTemplate(); }
  const empty = `<div class="empty catalog-empty"><b>이 브랜드에 판매 가능한 상품이 없어요.</b></div>`;
  return `${selectedBrandHero(brand)}<div id="marketProductGrid" class="panel seller-market-panel brand-products-panel"><div class="market-result-row"><span><b>${escapeHtml(brand.name)}</b> 상품 <b>${brand.products.length}</b>개</span>${marketViewToggle()}</div>${marketProductListing(brand.products, empty)}</div>`;
}

function sellerProductsTable() {
  const items = currentSellerProducts().filter(item => ["승인대기", "승인거절"].includes(item.approvalStatus)).sort((a, b) => Number(b.approvalStatus === "승인거절") - Number(a.approvalStatus === "승인거절"));
  if (!items.length) return `<div class="empty mapping-empty"><b>승인을 기다리는 상품이 없어요.</b><span>상품 소싱에서 마음에 드는 상품을 PICK해 보세요.</span></div>`;
  return `<div class="seller-product-tree">${items.map(item => {
    const product = productOf(item.productId);
    const rejected = item.approvalStatus === "승인거절";
    return `<article class="seller-product-node pick-approval-node ${rejected ? "is-rejected" : ""}">
      <div class="seller-product-parent pick-approval-row">
        ${productPhoto({ ...product, imageIndex: item.imageIndex }, "table-photo")}
        <span class="seller-product-main"><small>원본코드 ${escapeHtml(item.productId)} · ${escapeHtml(product?.supplier || "")}</small><strong>${escapeHtml(sellerProductTitle(item, product))}</strong><em>공급가 ${money(product?.supply || 0)} · 지정판매가 ${money(product?.recommended || 0)}</em></span>
        <span class="seller-product-price"><small>내가 판매하고 싶은 가격</small><b>${money(item.salePrice)}</b><em>마진 ${margin(product?.supply || 0, item.salePrice)}%</em></span>
        ${rejected
          ? `<span class="seller-product-live"><b class="approval-rejected-badge">승인 거절</b><small>사유: ${escapeHtml(item.rejectReason || "공급사 사정")}</small></span>
        <div class="pick-approval-actions"><button type="button" class="secondary-button" data-action="supplier-contact" data-id="${escapeHtml(product?.supplierLoginId || "")}" data-product-id="${escapeHtml(item.productId)}">공급사에 문의</button><button type="button" class="primary-button" data-action="rerequest-pick" data-id="${item.id}">다시 요청하기</button><button type="button" class="text-button danger-text" data-action="delete-pick" data-id="${item.id}">목록에서 삭제</button></div>`
          : `<span class="seller-product-live"><b class="approval-pending-badge">승인대기</b><small>${escapeHtml(product?.supplier || "공급사")} 확인 중 · 승인되면 알려 드려요</small></span>
        <div class="pick-approval-actions"><span class="pick-wait-note">공급사가 승인하면 알림으로 알려 드려요</span><button type="button" class="text-button danger-text" data-action="delete-pick" data-id="${item.id}">요청 취소</button></div>`}
      </div>
    </article>`;
  }).join("")}</div>`;
}

function supplierProductsTable() {
  const products = supplierLowStockOnly ? supplierLowStockProducts() : currentSupplierProducts();
  return `<div class="table-wrap"><table><thead><tr><th>상품</th><th>카테고리</th><th>공급가</th><th>권장 판매가</th><th>재고</th><th>셀러 선택</th><th>상태</th><th>관리</th></tr></thead><tbody>
    ${products.length ? products.map(product => `<tr><td><div class="table-product">${productPhoto(product, "table-photo")}<span><strong>${escapeHtml(product.name)}</strong><small>${product.id}${hasOptions(product) ? ` · <b class="option-pill">옵션 ${productOptions(product).length}개</b>` : ""}</small></span></div></td><td>${escapeHtml(product.category)}</td><td><strong>${productPriceLabel(product)}</strong></td><td>${productPriceLabel(product, "recommended")}</td><td><b class="${lowStockUnits(product).length ? "stock-low" : ""}">${product.stock}개</b>${hasOptions(product) && lowStockUnits(product).length ? `<small class="stock-low-note">옵션 ${lowStockUnits(product).length}개 부족</small>` : ""}</td><td>${state.sellerProducts.filter(item => item.productId === product.id).length}곳</td><td>${statusChip(product.status)}</td><td><div class="row-actions"><button class="small-button" data-action="edit-product" data-id="${product.id}">수정</button><button class="small-button" data-action="adjust-stock" data-id="${product.id}">재고</button><button class="small-button reject" data-action="change-price" data-id="${product.id}">가격</button></div></td></tr>`).join("") : `<tr><td colspan="8"><div class="empty">등록된 상품이 없습니다.</div></td></tr>`}
  </tbody></table></div>${supplierProductCards(products)}`;
}
/* 휴대폰: 공급사 상품을 카드로 (표는 PC에서만) */
function supplierProductCards(products) {
  if (!products.length) return `<div class="supplier-product-cards"><div class="empty">등록된 상품이 없습니다.</div></div>`;
  return `<div class="supplier-product-cards">${products.map(product => `<article class="supplier-product-card">
    <div class="supplier-product-card-top">${productPhoto(product, "supplier-card-photo")}<div><small>${escapeHtml(product.id)} · ${escapeHtml(product.category || "")}</small><strong>${escapeHtml(product.name)}</strong><span>${statusChip(product.status)}${hasOptions(product) ? `<b class="option-pill">옵션 ${productOptions(product).length}개</b>` : ""}</span></div></div>
    <dl><div><dt>공급가</dt><dd>${productPriceLabel(product)}</dd></div><div><dt>재고</dt><dd class="${lowStockUnits(product).length ? "stock-low" : ""}">${Number(product.stock || 0)}개${hasOptions(product) && lowStockUnits(product).length ? `<small class="stock-low-note">옵션 ${lowStockUnits(product).length}개 부족</small>` : ""}</dd></div><div><dt>가져간 셀러</dt><dd>${state.sellerProducts.filter(item => item.productId === product.id).length}곳</dd></div></dl>
    ${hasOptions(product) ? `<div class="supplier-card-options">${productOptions(product).map(option => `<span>${escapeHtml(option.name)} <b>${money(option.supply)}</b> <em class="${Number(option.stock || 0) < LOW_STOCK_LIMIT ? "stock-low" : ""}">재고 ${Number(option.stock || 0)}</em></span>`).join("")}</div>` : ""}
    <div class="supplier-card-actions"><button type="button" class="secondary-button" data-action="edit-product" data-id="${product.id}">수정</button><button type="button" class="secondary-button" data-action="adjust-stock" data-id="${product.id}">재고</button><button type="button" class="secondary-button" data-action="change-price" data-id="${product.id}">가격</button></div>
  </article>`).join("")}</div>`;
}

let masterProductQuery = "";
function masterProductsTable() {
  const query = masterProductQuery.trim().toLowerCase();
  const products = state.products;
  const raw = product => [product.id, product.name, supplierName(product.supplierLoginId), productBrand(product), product.category].join(" ").toLowerCase();
  const q = product => escapeHtml(raw(product));
  const hide = product => (query && !raw(product).includes(query) ? " hidden" : "");
  const picks = product => state.sellerProducts.filter(item => item.productId === product.id).length;
  const actions = product => `<button type="button" class="primary-button" data-action="master-edit-product" data-id="${product.id}">수정</button><button type="button" class="secondary-button" data-action="product-history" data-id="${product.id}">변경 이력</button>`;
  return `<label class="m-search"><span aria-hidden="true">⌕</span><input id="masterProductSearch" type="search" value="${escapeHtml(masterProductQuery)}" placeholder="상품명·상품코드·브랜드·공급사로 찾기" autocomplete="off"></label>
  <div class="table-wrap md-desktop"><table><thead><tr><th>상품</th><th>공급사 · 브랜드</th><th>카테고리</th><th>공급가</th><th>재고</th><th>선택 셀러</th><th>상태</th><th>관리</th></tr></thead><tbody>${products.map(product => `<tr data-q="${q(product)}"${hide(product)}><td><div class="table-product">${productPhoto(product, "table-photo")}<span><strong>${escapeHtml(product.name)}</strong><small>${product.id}</small></span></div></td><td>${escapeHtml(supplierName(product.supplierLoginId))}<br><small>${escapeHtml(productBrand(product))}</small></td><td>${escapeHtml(product.category)}</td><td>${money(product.supply)}</td><td><b class="${lowStockUnits(product).length ? "stock-low" : ""}">${product.stock}개</b></td><td>${picks(product)}곳</td><td>${statusChip(product.status)}</td><td><div class="row-actions">${actions(product)}</div></td></tr>`).join("") || ""}</tbody></table></div><div class="empty m-search-empty" hidden>찾는 상품이 없어요.</div>
  <div class="m-cards">${products.map(product => `<article class="m-card product" data-q="${q(product)}"${hide(product)}><div class="m-card-prod">${productPhoto(product, "m-card-photo")}<span><b>${escapeHtml(product.name)}</b><small>${product.id} · ${escapeHtml(productBrand(product))}</small><small>${escapeHtml(supplierName(product.supplierLoginId))} · ${escapeHtml(product.category || "")}</small></span></div>
    <dl class="four"><div><dt>공급가</dt><dd>${money(product.supply)}</dd></div><div><dt>판매가</dt><dd>${money(product.recommended)}</dd></div><div><dt>재고</dt><dd class="${lowStockUnits(product).length ? "stock-low" : ""}">${product.stock}개</dd></div><div><dt>상태</dt><dd>${statusChip(product.status)}</dd></div></dl>
    <div class="m-card-actions">${actions(product)}<small>셀러 ${picks(product)}곳 판매</small></div></article>`).join("")}</div>`;
}
document.addEventListener("change", event => {
  if (event.target.id !== "pgProductSelect") return;
  salesSellerPage = 1; priceGraphProductId = event.target.value; render(); updateAccountUI();
  document.querySelector(".price-graph")?.scrollIntoView({ block: "nearest" });
});
document.addEventListener("input", event => {
  if (event.target.id !== "masterProductSearch") return;
  masterProductQuery = event.target.value;
  const query = masterProductQuery.trim().toLowerCase();
  let shown = 0;
  document.querySelectorAll("#masterView [data-q]").forEach(row => { const match = !query || row.dataset.q.includes(query); row.hidden = !match; if (match && row.tagName === "ARTICLE") shown += 1; });
  const empty = document.querySelector(".m-search-empty"); if (empty) empty.hidden = shown > 0;
});

function masterPlanUsagePanel() {
  const sellers = [...new Set(["seller", ...state.members.filter(member => (member.roles || [member.role]).includes("seller")).map(member => member.loginId)])];
  const rows = sellers.map(loginId => { const tier = planTier(loginId), usage = planUsage(loginId), member = memberByLogin(loginId); return { loginId, tier, usage, name: member?.company || (loginId === "seller" ? "두고 셀러샵" : loginId), malls: connectedMallCount(loginId), kakao: kakaoAlertActive(loginId) && !tier.kakao }; });
  const revenue = rows.reduce((sum, row) => sum + row.tier.fee + (row.kakao ? PLAN_KAKAO_FEE : 0), 0);
  const nearLimit = rows.filter(row => row.tier.externalOrders && row.usage.externalOrders >= row.tier.externalOrders * .8).length;
  const doogo = rows.reduce((sum, row) => sum + Number(row.usage.doogoOrders || 0), 0), external = rows.reduce((sum, row) => sum + Number(row.usage.externalOrders || 0), 0);
  return `<div class="panel master-usage-panel"><div class="panel-head"><div><h3>요금제 · 이번 달 사용량</h3><p>두고 상품 주문은 수수료로, 다른 상품 주문은 요금제로 비용을 메워요. 다른 상품 주문 비중이 높은데 한도에 가까운 셀러는 요금제 안내 대상이에요.</p></div></div>
    <div class="master-usage-kpis"><div><span>이번 달 구독 매출</span><strong>${money(revenue)}</strong></div><div><span>두고 상품 주문</span><strong>${doogo.toLocaleString("ko-KR")}건</strong></div><div><span>다른 상품 주문</span><strong>${external.toLocaleString("ko-KR")}건</strong></div><div class="${nearLimit ? "warn" : ""}"><span>한도 80% 넘은 셀러</span><strong>${nearLimit}곳</strong></div></div>
    <div class="table-wrap"><table class="master-usage-table"><thead><tr><th>위탁셀러</th><th>요금제</th><th>쇼핑몰</th><th>두고 주문</th><th>다른 상품 주문</th><th>초과로 건너뜀</th><th>상품 전송</th></tr></thead><tbody>${rows.map(row => { const ratio = row.tier.externalOrders ? row.usage.externalOrders / row.tier.externalOrders : 0; const share = row.usage.doogoOrders + row.usage.externalOrders ? Math.round(row.usage.doogoOrders / (row.usage.doogoOrders + row.usage.externalOrders) * 100) : 0; return `<tr><td><b>${escapeHtml(row.name)}</b><small>${escapeHtml(row.loginId)}</small></td><td>${statusChip(row.tier.name)}<small>${money(row.tier.fee)}</small></td><td>${row.malls} / ${row.tier.malls}</td><td>${Number(row.usage.doogoOrders).toLocaleString("ko-KR")}<small>두고 비중 ${share}%</small></td><td class="${ratio >= 1 ? "full" : ratio >= .8 ? "warn" : ""}">${Number(row.usage.externalOrders).toLocaleString("ko-KR")} / ${limitText(row.tier.externalOrders)}</td><td>${Number(row.usage.externalSkipped || 0).toLocaleString("ko-KR")}</td><td>${Number(row.usage.productSends).toLocaleString("ko-KR")} / ${limitText(row.tier.productSends)}</td></tr>`; }).join("")}</tbody></table></div></div>`;
}
function memberDirectoryTable(role) {
  const members = state.members.filter(member => (member.roles || [member.role]).includes(role));
  const info = member => {
    const orders = state.orders.filter(order => role === "supplier" ? orderSupplierId(order) === member.loginId : order.sellerLoginId === member.loginId);
    const month = usageMonthKey();
    const monthSales = orders.filter(order => String(order.orderDate).startsWith(month) && orderPaymentStatus(order) !== "pending" && settlementOrderState(order).state !== "excluded");
    const amount = monthSales.reduce((sum, order) => sum + (role === "supplier" ? orderSupplyAmount(order) : Number(order.amount || 0)), 0);
    const volume = role === "supplier" ? `상품 ${state.products.filter(product => product.supplierLoginId === member.loginId).length}개 · 주문 ${orders.length}건` : `주문 ${orders.length}건 · ${planTier(member.loginId).name}`;
    const company = role === "supplier" ? (member.supplierCompany || member.company) : member.company;
    const sanctioned = ["suspended", "banned"].includes(member.status);
    const actions = `<button type="button" class="secondary-button" data-action="member-detail" data-id="${member.id}">상세</button><button type="button" class="secondary-button" data-action="support-open-thread" data-login="${escapeHtml(member.loginId)}" data-role="${role}">두고톡</button>${member.status === "approved" || sanctioned ? `<button type="button" class="${sanctioned ? "primary-button" : "secondary-button danger"}" data-action="member-sanction" data-id="${member.id}">${sanctioned ? "정지 관리" : "정지"}</button>` : ""}`;
    return { company, volume, amount, actions, sanctioned };
  };
  if (!members.length) return `<div class="empty">해당 회원이 없습니다.</div>`;
  return `<div class="table-wrap md-desktop"><table><thead><tr><th>사업자</th><th>대표자</th><th>사업자등록번호</th><th>연락처</th><th>상품/주문</th><th>이번 달 ${role === "supplier" ? "거래액" : "판매액"}</th><th>상태</th><th>관리</th></tr></thead><tbody>
    ${members.map(member => { const row = info(member); return `<tr><td><strong>${escapeHtml(row.company)}</strong>${(member.roles || []).length > 1 ? ` <span class="dual-role-badge">복수역할</span>` : ""}<br><small>${escapeHtml(member.loginId)}</small></td><td>${escapeHtml(member.representative)}</td><td>${escapeHtml(member.businessNo)}</td><td>${escapeHtml(member.contact)}</td><td>${row.volume}</td><td><b>${money(row.amount)}</b></td><td>${memberStatusChip(member.status)}${member.suspendedUntil ? `<br><small>${escapeHtml(member.suspendedUntil)}까지</small>` : ""}</td><td><div class="row-actions">${row.actions}</div></td></tr>`; }).join("")}
  </tbody></table></div>
  <div class="m-cards">${members.map(member => { const row = info(member); return `<article class="m-card ${row.sanctioned ? "sanctioned" : ""}"><div class="m-card-head"><span><b>${escapeHtml(row.company)}</b><small>${escapeHtml(member.representative || "")} · ${escapeHtml(member.loginId)}</small></span>${memberStatusChip(member.status)}</div>
    <dl><div><dt>이번 달 ${role === "supplier" ? "거래액" : "판매액"}</dt><dd>${money(row.amount)}</dd></div><div><dt>${role === "supplier" ? "상품·주문" : "주문·요금제"}</dt><dd>${row.volume}</dd></div><div><dt>연락처</dt><dd>${escapeHtml(member.contact || "-")}</dd></div><div><dt>사업자번호</dt><dd>${escapeHtml(member.businessNo || "-")}</dd></div>${row.sanctioned ? `<div class="wide"><dt>정지 사유</dt><dd>${escapeHtml(member.sanctionReason || "")}${member.suspendedUntil ? ` · ${escapeHtml(member.suspendedUntil)}까지` : ""}</dd></div>` : ""}</dl>
    <div class="m-card-actions">${row.actions}</div></article>`; }).join("")}</div>`;
}

