  if (carrierCol >= 0) sheets.push({ name: "택배사 목록", rows: [["택배사 (스마트스토어 기준)", "구분", "네이버 코드"], ...CARRIERS.map(item => [item.name, item.group || "", item.naver || "CH1 (기타)"])], widths: [26, 14, 16] });
